"""stages.verify.cost: generated by the graph.py split (P1)."""

from __future__ import annotations

from pathlib import Path

from ...flow import gates, ladder, outcome
from ...runtime import cost_budget, effects, commands, dependencies, rtl_snapshot, stage_services, validation_parallel
from ...runtime.tools import SOC_WORKSPACE_SUBDIR
from ...stages.verify import software
from ...state import CfuDesignState


def _check_cost_wall(state: CfuDesignState, result: dict, *, top: str,
                     summary_path: str) -> dict:
    parsed = result.get("parsed")
    if not isinstance(parsed, dict):
        parsed = {}
    wall = cost_budget.check(state, parsed.get("cost"), top=top, summary_path=summary_path)
    parsed["cost_wall"] = wall
    result["parsed"] = parsed
    return wall


def _cost_wall_failure(state: CfuDesignState, wall: dict, errors: list[str]) -> dict:
    result = stage_services.gate_failure_result(
        state, "cost", wall["code"], errors, category=wall["code"])
    result["parsed"] = {"cost_wall": wall}
    # The authoritative record is the cost artifact, not a nonexistent validation file.
    result["log_path"] = f"{state.get('run_root', '')}/11_cost/result.yaml"
    if result.get("failure_observation"):
        result["failure_observation"]["log_path"] = result["log_path"]
    return result


def estimate_cost(state: CfuDesignState, *, transition: bool = True) -> CfuDesignState:
    if state.get("cost_backend", "yosys") == "vivado":
        return _estimate_vivado(state, transition=transition)
    if state.get("skip_yosys", False) or state.get("skip_cost", False):
        reason = "--skip-cost" if state.get("skip_cost") else "--skip-yosys"
        result = [stage_services._skipped_result("python3 skills/cfu-designer/scripts/yosys_cost_report.py", state, reason)]
        stage_services._write_cost_artifact(state, result, "planned", reason)
        return {
            "cost_results": result,
            "stage_jobs": "review",
            **outcome.stage_result(state, rung="cost", ok=False, skipped=True,
                                   reason=reason,
                                   history="Skipped Yosys cost estimation by request."),
        }

    toolbox = stage_services._toolbox_for_stage(state, "cost")
    agent_cfu = gates.is_agent_cfu_run(state)
    spec = state.get("workload_spec", {}) or {}
    task = state.get("task", "")
    case = commands.cost_case_for_spec(spec, task, agent_cfu=agent_cfu)
    execute = bool(state.get("run_commands", False)) and not state.get("dry_run", False)
    workdir = Path(state.get("workdir", ".")).resolve()

    # Command side effects must stay inside the stage's declared write roots, so
    # the report goes into the run directory when one exists.
    run_root = state.get("run_root", "")
    if run_root:
        out_dir = f"{run_root}/11_cost/yosys/{case}"
        # NOTE: the cost rung derives its AgentCfu flags from the ISA spec
        # internally -- never pass the workload spec here (that mismatch made
        # cost re-elaborate the CFU with default parameters).
        generator_commands = commands.agent_cfu_cost_commands(state) if agent_cfu else []
        rtl = (
            f"{run_root}/11_cost/cfu_rtl"
            if generator_commands
            else f"{run_root}/{SOC_WORKSPACE_SUBDIR}/MiCoSoc.v"
        )
    else:
        out_dir = f"{stage_services.base_artifact_root(state)}/yosys/{case}"
        generator_commands = []
        rtl = "MiCoSoc.v"

    yosys_command = [
        "python3",
        "skills/cfu-designer/scripts/yosys_cost_report.py",
        rtl,
        "--top",
        commands.cost_top_for_spec(spec, task, agent_cfu=agent_cfu),
        "--out-dir",
        out_dir,
        "--flatten",
    ]

    results: list[dict] = []
    errors: list[str] = []
    wall: dict = {}
    cancelled = False
    if not execute:
        for argv in [*generator_commands, yosys_command]:
            results.append(toolbox.run_command(argv, execute=False))
        ok = False
    else:
        # Agent runs synthesize the standalone CFU first: GenAgentCfu elaborates
        # only the overlaid AgentCfu class, so Yosys never sees the CPU/SoC.
        for argv in generator_commands:
            result = effects.run_command(state, toolbox, argv, stage="cost", rung="cost", timeout=1800, mutate=True)
            results.append(result)
            if result.get("cancelled"):
                cancelled = True
                break
            if result.get("returncode") not in (0, None):
                errors.append(f"CFU generation failed: {' '.join(argv)[:200]}")
                break
        if not cancelled and not errors and generator_commands and not software._rtl_ready(workdir, rtl):
            errors.append(f"CFU generation produced no Verilog under {rtl}")
        if not cancelled and not errors:
            result = effects.run_command(state, toolbox, yosys_command, stage="cost", rung="cost", timeout=1800, mutate=True)
            results.append(result)
            if result.get("cancelled"):
                cancelled = True
            elif result.get("returncode") not in (0, None):
                errors.append(f"Yosys cost estimation failed: {' '.join(yosys_command)[:200]}")
            elif result.get("returncode") == 0:
                wall = _check_cost_wall(
                    state, result, top=commands.cost_top_for_spec(spec, task, agent_cfu=agent_cfu),
                    summary_path=f"{out_dir}/summary.json")
                if not wall["ok"]:
                    errors.append(wall["reason"])
                    results.append(_cost_wall_failure(state, wall, errors))
        ok = not cancelled and not errors and bool(results) and all(item.get("returncode") == 0 for item in results)

    if not ok and execute and not cancelled and not transition:
        validation_parallel.command_failed()
    reason = "; ".join(errors)[:800] if errors else ""
    stage_services._write_cost_artifact(
        state, results, "cancelled" if cancelled else "passed" if ok else ("planned" if not execute else "failed"), reason
    )
    extra, next_node = ({}, None)
    if transition:
        extra, next_node = ladder._ladder_transition(
            state, "cost", ok=ok, default="review_and_route",
            repair_target="implement", skipped=not execute or cancelled,
        )
    update = {
        "cost_results": results,
        "stage_jobs": "review",
        "errors": errors if not cancelled else [],
        **outcome.stage_result(
            state, rung="cost", ok=ok, skipped=not execute, next=next_node,
            reason=reason or ("" if execute else "execution-disabled"),
            cancelled=cancelled, cost_wall=wall,
            rtl=rtl, round=int(state.get("optimization_round", 0) or 0),
            history="Ran Yosys cost estimation.",
        ),
    }
    return ladder._apply_transition(update, extra)


def _estimate_vivado(state: CfuDesignState, *, transition: bool) -> CfuDesignState:
    """Run a Yosys synthesis gate before Vivado on the frozen candidate."""
    from ...runtime import vivado
    import re
    import uuid

    execute = bool(state.get("run_commands")) and not state.get("dry_run")
    skipped = bool(state.get("skip_cost")) or not execute
    reason = "--skip-cost" if state.get("skip_cost") else ("execution-disabled" if not execute else "")
    results: list[dict] = []
    errors: list[str] = []
    ppa: dict = {}
    yosys_evidence: dict = {}
    wall: dict = {}
    cancelled = False
    run = str(state.get("run_root") or "")
    evaluation_id = str(state.get("evaluation_id") or f"cost-{uuid.uuid4().hex}")
    if not re.fullmatch(r"[a-zA-Z0-9_-]+", evaluation_id):
        raise ValueError("invalid evaluation id")
    eval_root = f"{run}/11_cost/evaluations/{evaluation_id}"
    yosys_out = f"{eval_root}/yosys"
    yosys_rtl = f"{yosys_out}/rtl"
    vivado_out = f"{eval_root}/vivado"
    cost_input = dependencies.input_fingerprints(state)["cost"]
    snapshot: dict = {}
    if skipped:
        results = [
            stage_services._skipped_result(
                ["python3", "skills/cfu-designer/scripts/yosys_cost_report.py"], state, reason),
            stage_services._skipped_result(
                ["python3", "skills/cfu-designer/scripts/vivado_ppa_report.py"], state, reason),
        ]
    else:
        toolbox = stage_services._toolbox_for_stage(state, "cost")
        try:
            if state.get("skip_yosys"):
                raise ValueError("--skip-yosys cannot bypass Vivado's mandatory Yosys precheck; use --skip-cost")
            snapshot = rtl_snapshot.validate(state)

            # Keep the early gate small: synthesize standalone AgentCfu for agent
            # runs, or the selected CFU module from the frozen SoC RTL otherwise.
            agent_cfu = gates.is_agent_cfu_run(state)
            generator_commands = (commands.agent_cfu_cost_commands(state, out_dir=yosys_rtl)
                                 if agent_cfu else [])
            if agent_cfu and not generator_commands:
                errors.append("Yosys precheck could not create standalone AgentCfu RTL")
            spec = state.get("workload_spec", {}) or {}
            task = state.get("task", "")
            yosys_input = yosys_rtl if agent_cfu else f"{snapshot['root']}/MiCoSoc.v"
            yosys_top = "AgentCfu" if agent_cfu else commands.cost_top_for_spec(spec, task)

            for argv in generator_commands:
                result = effects.run_command(
                    state, toolbox, argv, stage="cost", rung="cost", timeout=1800, mutate=True)
                results.append(result)
                if result.get("cancelled"):
                    break
                if result.get("returncode") != 0:
                    errors.append(f"AgentCfu RTL generation for Yosys failed (returncode={result.get('returncode')})")
                    break
            cancelled = any(item.get("cancelled") for item in results)
            if not cancelled and not errors and generator_commands and not software._rtl_ready(
                    Path(state.get("workdir", ".")).resolve(), yosys_input):
                errors.append(f"AgentCfu Yosys RTL generation produced no Verilog under {yosys_input}")

            if not cancelled and not errors:
                yosys_argv = [
                    "python3", "skills/cfu-designer/scripts/yosys_cost_report.py",
                    yosys_input, "--top", yosys_top, "--out-dir", yosys_out, "--flatten",
                ]
                result = effects.run_command(
                    state, toolbox, yosys_argv, stage="cost", rung="cost", timeout=1800, mutate=True)
                results.append(result)
                if result.get("cancelled"):
                    cancelled = True
                elif result.get("returncode") != 0:
                    errors.append(
                        f"Yosys pre-synthesis failed (returncode={result.get('returncode')}); Vivado was not started")
                else:
                    wall = _check_cost_wall(
                        state, result, top=yosys_top, summary_path=f"{yosys_out}/summary.json")
                    metrics = result["parsed"].get("cost")
                    yosys_evidence = {
                        "status": "passed", "top": yosys_top,
                        "metrics": dict(metrics) if isinstance(metrics, dict) else {},
                        "summary_path": f"{yosys_out}/summary.json", "cost_wall": wall,
                    }
                    if not wall["ok"]:
                        errors.append(f"{wall['reason']} Vivado was not started.")

            # Expensive vendor implementation requires both successful Yosys and a passing Cost Wall.
            if not cancelled and not errors:
                argv = vivado.build_command(state, snapshot["root"], vivado_out)
                result = effects.run_command(
                    state, toolbox, argv, stage="cost", rung="cost", command_id="vivado_cost",
                    timeout=int(state.get("eda_timeout", 3600)) + 30, mutate=True)
                results.append(result)
                if result.get("cancelled"):
                    cancelled = True
                else:
                    try:
                        ppa = vivado.load_summary(Path(state.get("workdir", ".")), vivado_out)
                    except (OSError, ValueError) as exc:
                        errors.append(f"Vivado produced no valid PPA summary: {exc}")
                    if result.get("returncode") != 0:
                        errors.append(f"Vivado FPGA evaluation failed (returncode={result.get('returncode')})")
                    if ppa and ppa.get("status") != "passed":
                        blocking = [item for item in ppa.get("issues", [])
                                    if not isinstance(item, dict) or item.get("severity", "error") == "error"]
                        errors.extend((f"{item.get('code', 'fpga')}: {item.get('detail', '')}"
                                       if isinstance(item, dict) else str(item))
                                      for item in blocking or ["Vivado implementation/timing did not pass"])
        except (OSError, ValueError) as exc:
            errors.append(f"Cost evaluation precondition failed: {exc}")
    cancelled = cancelled or any(item.get("cancelled") for item in results)
    if ppa:
        ppa["yosys_precheck"] = yosys_evidence
        ppa["evidence"] = {"evaluation_id": evaluation_id, "input_sha256": cost_input,
                           "rtl_sha256": snapshot.get("sha256"),
                           "summary_path": f"{vivado_out}/summary.json"}
        # A PPA summary is produced only after the Vivado command was appended.
        results[-1].setdefault("parsed", {})["ppa"] = ppa
    ok = not skipped and not cancelled and not errors and bool(ppa) and ppa.get("status") == "passed"
    if errors and not cancelled:
        if not transition:
            validation_parallel.command_failed()
        results.append(_cost_wall_failure(state, wall, errors) if wall and not wall["ok"]
                       else stage_services.gate_failure_result(state, "cost", "fpga_ppa", errors))
    for result in results:
        result["evaluation_id"] = evaluation_id
    reason = "; ".join(errors)[:800] if errors else reason
    stage_services._write_cost_artifact(
        state, results, "cancelled" if cancelled else "passed" if ok else "planned" if skipped else "failed", reason)
    extra, next_node = ({}, None)
    if transition:
        extra, next_node = ladder._ladder_transition(
            state, "cost", ok=ok, skipped=skipped or cancelled,
            default="review_and_route", repair_target="implement")
    update = {"cost_results": results, "stage_jobs": "review", "errors": errors if not cancelled else [],
              **outcome.stage_result(
                  state, rung="cost", ok=ok, skipped=skipped, next=next_node,
                  reason=reason, cancelled=cancelled, backend="vivado", evaluation_id=evaluation_id,
                  ppa=ppa, input_sha256=cost_input, cost_wall=wall, yosys_precheck=yosys_evidence,
                  round=int(state.get("optimization_round", 0) or 0),
                  history=("Passed Yosys pre-synthesis and Cost Wall before whole-SoC Vivado PPA."
                            if ok else "Vivado cost evaluation did not pass; see cost gate evidence."))}
    return ladder._apply_transition(update, extra)
